export interface TaskInput {
  id: string;
  duration: number;
  dependsOn?: string[];
}

export interface Plan {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
}

interface Task {
  id: string;
  duration: number;
  dependsOn: string[];
}

interface PathNode {
  id: string;
  previous?: PathNode;
}

const compareIds = (left: string, right: string): number =>
  left < right ? -1 : left > right ? 1 : 0;

function comparePaths(left: string[], right: string[]): number {
  const commonLength = Math.min(left.length, right.length);
  for (let index = 0; index < commonLength; index += 1) {
    const comparison = compareIds(left[index]!, right[index]!);
    if (comparison !== 0) return comparison;
  }
  return left.length - right.length;
}

function materializePath(node: PathNode): string[] {
  const path: string[] = [];
  for (let current: PathNode | undefined = node; current; current = current.previous) {
    path.push(current.id);
  }
  path.reverse();
  return path;
}

function comparePathNodes(left: PathNode, right: PathNode): number {
  return comparePaths(materializePath(left), materializePath(right));
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function validateInput(input: unknown): Task[] {
  if (!isRecord(input)) {
    throw new Error("input must be a JSON object");
  }
  if (!Array.isArray(input.tasks)) {
    throw new Error('"tasks" must be an array');
  }

  const tasks: Task[] = [];
  const ids = new Set<string>();

  for (let index = 0; index < input.tasks.length; index += 1) {
    const rawTask: unknown = input.tasks[index];
    const location = `tasks[${index}]`;
    if (!isRecord(rawTask)) {
      throw new Error(`${location} must be an object`);
    }

    if (typeof rawTask.id !== "string" || rawTask.id.length === 0) {
      throw new Error(`${location}.id must be a non-empty string`);
    }
    if (ids.has(rawTask.id)) {
      throw new Error(`duplicate task id: ${JSON.stringify(rawTask.id)}`);
    }
    if (
      typeof rawTask.duration !== "number" ||
      !Number.isFinite(rawTask.duration) ||
      rawTask.duration < 0
    ) {
      throw new Error(`${location}.duration must be a finite non-negative number`);
    }

    const rawDependencies = rawTask.dependsOn === undefined ? [] : rawTask.dependsOn;
    if (!Array.isArray(rawDependencies)) {
      throw new Error(`${location}.dependsOn must be an array`);
    }

    const dependsOn: string[] = [];
    const dependencies = new Set<string>();
    for (let dependencyIndex = 0; dependencyIndex < rawDependencies.length; dependencyIndex += 1) {
      const dependency: unknown = rawDependencies[dependencyIndex];
      if (typeof dependency !== "string") {
        throw new Error(`${location}.dependsOn[${dependencyIndex}] must be a string`);
      }
      if (dependencies.has(dependency)) {
        throw new Error(
          `${location}.dependsOn contains duplicate id: ${JSON.stringify(dependency)}`,
        );
      }
      dependencies.add(dependency);
      dependsOn.push(dependency);
    }

    ids.add(rawTask.id);
    tasks.push({ id: rawTask.id, duration: rawTask.duration, dependsOn });
  }

  for (let index = 0; index < tasks.length; index += 1) {
    const task = tasks[index]!;
    for (const dependency of task.dependsOn) {
      if (dependency === task.id) {
        throw new Error(`task ${JSON.stringify(task.id)} cannot depend on itself`);
      }
      if (!ids.has(dependency)) {
        throw new Error(
          `task ${JSON.stringify(task.id)} references unknown dependency ${JSON.stringify(dependency)}`,
        );
      }
    }
    task.dependsOn.sort(compareIds);
  }

  return tasks;
}

class MinHeap {
  private readonly values: string[] = [];

  get size(): number {
    return this.values.length;
  }

  push(value: string): void {
    let index = this.values.length;
    this.values.push(value);
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (compareIds(this.values[parent]!, value) <= 0) break;
      this.values[index] = this.values[parent]!;
      index = parent;
    }
    this.values[index] = value;
  }

  pop(): string {
    const first = this.values[0]!;
    const last = this.values.pop()!;
    if (this.values.length === 0) return first;

    let index = 0;
    while (true) {
      const left = index * 2 + 1;
      if (left >= this.values.length) break;
      const right = left + 1;
      const child =
        right < this.values.length && compareIds(this.values[right]!, this.values[left]!) < 0
          ? right
          : left;
      if (compareIds(this.values[child]!, last) >= 0) break;
      this.values[index] = this.values[child]!;
      index = child;
    }
    this.values[index] = last;
    return first;
  }
}

function canonicalizeCycle(cycle: string[]): string[] {
  const nodes = cycle.slice(0, -1);
  let smallestIndex = 0;
  for (let index = 1; index < nodes.length; index += 1) {
    if (compareIds(nodes[index]!, nodes[smallestIndex]!) < 0) smallestIndex = index;
  }
  const rotated = nodes.slice(smallestIndex).concat(nodes.slice(0, smallestIndex));
  rotated.push(rotated[0]!);
  return rotated;
}

function findCycle(tasksById: Map<string, Task>): string[] {
  const state = new Map<string, 0 | 1 | 2>();
  const sortedIds = [...tasksById.keys()].sort(compareIds);

  for (const initialId of sortedIds) {
    if ((state.get(initialId) ?? 0) !== 0) continue;

    const path: string[] = [initialId];
    const pathPositions = new Map<string, number>([[initialId, 0]]);
    const frames: Array<{ id: string; nextDependency: number }> = [
      { id: initialId, nextDependency: 0 },
    ];
    state.set(initialId, 1);

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]!;
      const dependencies = tasksById.get(frame.id)!.dependsOn;
      if (frame.nextDependency >= dependencies.length) {
        frames.pop();
        path.pop();
        pathPositions.delete(frame.id);
        state.set(frame.id, 2);
        continue;
      }

      const dependency = dependencies[frame.nextDependency++]!;
      const dependencyState = state.get(dependency) ?? 0;
      if (dependencyState === 1) {
        const start = pathPositions.get(dependency)!;
        return canonicalizeCycle(path.slice(start).concat(dependency));
      }
      if (dependencyState === 0) {
        state.set(dependency, 1);
        pathPositions.set(dependency, path.length);
        path.push(dependency);
        frames.push({ id: dependency, nextDependency: 0 });
      }
    }
  }
  throw new Error("cycle detected");
}

export function createPlan(tasks: Task[]): Plan {
  const tasksById = new Map(tasks.map((task) => [task.id, task]));
  const dependents = new Map<string, string[]>();
  const remainingDependencies = new Map<string, number>();

  for (const task of tasks) {
    dependents.set(task.id, []);
    remainingDependencies.set(task.id, task.dependsOn.length);
  }
  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      dependents.get(dependency)!.push(task.id);
    }
  }
  for (const taskDependents of dependents.values()) taskDependents.sort(compareIds);

  const ready = new MinHeap();
  for (const task of tasks) {
    if (task.dependsOn.length === 0) ready.push(task.id);
  }

  const order: string[] = [];
  while (ready.size > 0) {
    const id = ready.pop();
    order.push(id);
    for (const dependent of dependents.get(id)!) {
      const remaining = remainingDependencies.get(dependent)! - 1;
      remainingDependencies.set(dependent, remaining);
      if (remaining === 0) ready.push(dependent);
    }
  }

  if (order.length !== tasks.length) {
    const cycle = findCycle(tasksById);
    throw new Error(`dependency cycle: ${cycle.join(" -> ")}`);
  }

  const earliestById = new Map<string, { start: number; finish: number }>();
  const layerById = new Map<string, number>();
  const bestScoreById = new Map<string, number>();
  const bestPathById = new Map<string, PathNode>();
  const layers: string[][] = [];

  let totalDuration = 0;
  let criticalPathNode: PathNode | undefined;

  for (const id of order) {
    const task = tasksById.get(id)!;
    let start = 0;
    let layer = 0;
    let bestScore = task.duration;
    let bestPath: PathNode = { id };

    for (const dependency of task.dependsOn) {
      start = Math.max(start, earliestById.get(dependency)!.finish);
      layer = Math.max(layer, layerById.get(dependency)! + 1);

      const candidateScore = bestScoreById.get(dependency)! + task.duration;
      const candidatePath: PathNode = { id, previous: bestPathById.get(dependency)! };
      if (
        candidateScore > bestScore ||
        (candidateScore === bestScore && comparePathNodes(candidatePath, bestPath) < 0)
      ) {
        bestScore = candidateScore;
        bestPath = candidatePath;
      }
    }

    const finish = start + task.duration;
    earliestById.set(id, { start, finish });
    layerById.set(id, layer);
    bestScoreById.set(id, bestScore);
    bestPathById.set(id, bestPath);
    (layers[layer] ??= []).push(id);

    if (
      bestScore > totalDuration ||
      (bestScore === totalDuration &&
        (criticalPathNode === undefined || comparePathNodes(bestPath, criticalPathNode) < 0))
    ) {
      totalDuration = bestScore;
      criticalPathNode = bestPath;
    }
  }

  for (const currentLayer of layers) currentLayer.sort(compareIds);

  const earliest = Object.create(null) as Record<string, { start: number; finish: number }>;
  for (const id of [...tasksById.keys()].sort(compareIds)) {
    earliest[id] = earliestById.get(id)!;
  }

  const criticalPath = criticalPathNode ? materializePath(criticalPathNode) : [];
  return { order, layers, earliest, totalDuration, criticalPath };
}

export function plan(input: unknown): Plan {
  return createPlan(validateInput(input));
}

async function runCli(): Promise<void> {
  const args = process.argv.slice(2);
  if (args.length === 0) throw new Error("missing command; usage: cli.ts plan INPUT.json");
  if (args[0]!.startsWith("-")) throw new Error(`unknown flag: ${args[0]}`);
  if (args[0] !== "plan") throw new Error(`unknown command: ${args[0]}`);
  if (args.length === 1) throw new Error("missing input file; usage: cli.ts plan INPUT.json");
  const unknownFlag = args.slice(1).find((argument) => argument.startsWith("-"));
  if (unknownFlag) throw new Error(`unknown flag: ${unknownFlag}`);
  if (args.length > 2) throw new Error(`unexpected argument: ${args[2]}`);

  let source: string;
  try {
    source = await Bun.file(args[1]!).text();
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`cannot read input file ${JSON.stringify(args[1])}: ${detail}`);
  }

  let input: unknown;
  try {
    input = JSON.parse(source);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`invalid JSON in ${JSON.stringify(args[1])}: ${detail}`);
  }

  process.stdout.write(`${JSON.stringify(plan(input))}\n`);
}

if (import.meta.main) {
  runCli().catch((error: unknown) => {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`Error: ${message}\n`);
    process.exitCode = 1;
  });
}
